\"\"\"Minimal, standard-library-only client for the OpenAI Responses API.

Prompts are sent with "'``store: false`` by default so responses are not
retained for later retrieval via the API.

Usage:
    export OPENAI_API_KEY=sk-...
    python3 openai_client.py "Explain recursion briefly"

    from openai_client import OpenAIClient
    print(OpenAIClient().ask("Hello"))
"""

from __future__ import annotations

import json
import os
import sys
import time
import urllib.error
import urllib.request
from typing import Any, Dict, Optional

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4.1-mini"
RETRYABLE_STATUS = {408, 409, 429, 500, 502, 503, 504}


class OpenAIError(Exception):
    """Raised when the API returns an error or cannot be reached."""

    def __init__(self, message: str, status: Optional[int] = None, body: Any = None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        model: Optional[str] = None,
        base_url: Optional[str] = None,
        timeout: float = 60.0,
        max_retries: int = 2,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIError("Missing API key: pass api_key or set OPENAI_API_KEY.")
        self.model = model or os.environ.get("OPENAI_MODEL", DEFAULT_MODEL)
        self.base_url = (base_url or os.environ.get("OPENAI_BASE_URL", DEFAULT_BASE_URL)).rstrip("/")
        if not self.base_url.startswith("https://"):
            raise OpenAIError("Refusing non-HTTPS base URL; prompts must be sent encrypted.")
        self.timeout = timeout
        self.max_retries = max_retries

    def __repr__(self) -> str:
        return f"OpenAIClient(model={self.model!r}, base_url={self.base_url!r})"

    def create_response(
        self,
        prompt: str,
        *,
        instructions: Optional[str] = None,
        model: Optional[str] = None,
        store: bool = False,
        **extra: Any,
    ) -> Dict[str, Any]:
        """POST /responses and return the parsed JSON response."""
        payload: Dict[str, Any] = {"model": model or self.model, "input": prompt, "store": store}
        if instructions:
            payload["instructions"] = instructions
        payload.update(extra)
        return self._post("/responses", payload)

    def ask(self, prompt: str, **kwargs: Any) -> str:
        """Send a text prompt and return the model'"'s text output.\"\"\"
        return extract_text(self.create_response(prompt, **kwargs))

    def _post(self, path: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        data = json.dumps(payload).encode(\"utf-8\")
        headers = {
            \"Authorization\": f\"Bearer {self.api_key}\",
            \"Content-Type\": \"application/json\",
            \"Accept\": \"application/json\",
        }
        attempt = 0
        while True:
            request = urllib.request.Request(self.base_url + path, data=data, headers=headers, method=\"POST\")
            try:
                with urllib.request.urlopen(request, timeout=self.timeout) as resp:
                    return json.loads(resp.read().decode(\"utf-8\"))
            except urllib.error.HTTPError as exc:
                raw = exc.read().decode(\"utf-8\", errors=\"replace\")
                try:
                    body: Any = json.loads(raw)
                    message = body.get(\"error\", {}).get(\"message\") or raw
                except (ValueError, AttributeError):
                    body, message = raw, raw
                if exc.code in RETRYABLE_STATUS and attempt < self.max_retries:
                    attempt += 1
                    time.sleep(_retry_delay(exc.headers.get(\"Retry-After\"), attempt))
                    continue
                raise OpenAIError(f\"HTTP {exc.code}: {message}\", exc.code, body) from None
            except (urllib.error.URLError, TimeoutError) as exc:
                if attempt < self.max_retries:
                    attempt += 1
                    time.sleep(_retry_delay(None, attempt))
                    continue
                raise OpenAIError(f\"Request failed: {exc}\") from None


def _retry_delay(retry_after: Optional[str], attempt: int) -> float:
    try:
        return min(float(retry_after), 30.0) if retry_after else min(2.0 ** attempt, 30.0)
    except ValueError:
        return min(2.0 ** attempt, 30.0)


def extract_text(response: Dict[str, Any]) -> str:
    \"\"\"Concatenate all output_text parts from a Responses API result.\"\"\"
    if isinstance(response.get(\"output_text\"), str):
        return response[\"output_text\"]
    parts = []
    for item in response.get(\"output\", []) or []:
        if item.get(\"type\") "'!= "message":
            continue
        for content in item.get("content", []) or []:
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
            elif content.get("type") == "refusal":
                parts.append(content.get("refusal", ""))
    return "".join(parts)


def main(argv: Optional[list] = None) -> int:
    import argparse

    parser = argparse.ArgumentParser(description="Send a private prompt to the OpenAI Responses API.")
    parser.add_argument("prompt", nargs="?", help="Prompt text (reads stdin if omitted)")
    parser.add_argument("-m", "--model", help="Model name (default: $OPENAI_MODEL or %s)" % DEFAULT_MODEL)
    parser.add_argument("-i", "--instructions", help="System/developer instructions")
    args = parser.parse_args(argv)

    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    if not prompt.strip():
        parser.error("empty prompt")
    try:
        print(OpenAIClient(model=args.model).ask(prompt, instructions=args.instructions))
    except OpenAIError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
